import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(bytes32 guess) public {
        // 1. fund the test contract with enough ether to call lockInGuess
        vm.deal(address(this), 1 ether);
        // 2. call lockInGuess with the fuzzed guess
        c.lockInGuess{value: 1 ether}(guess);
        // 3. get the recorded block using the auto-generated getter for the public mapping
        //    guesses(address) returns (uint block, bytes32 guess)
        (uint recordedBlock, bytes32 recordedGuess) = c.guesses(address(this));
        // Assert that the recorded block is strictly greater than the current block.
