pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C{value: 1 ether}();
    }

    function testFuzz_property(uint256 fuzzBlockDelta, uint256 fuzzBlockNumber) public {
        // Bound blockDelta to ensure block.number + delta > block.number for settle requirement
        fuzzBlockDelta = bound(fuzzBlockDelta, 2, 256);
        fuzzBlockNumber = bound(fuzzBlockNumber, fuzzBlockDelta, 1000);
        vm.assume(fuzzBlockNumber >= fuzzBlockDelta);

        address alice = address(0x1000);
        vm.deal(alice, 1 ether);

        // Warp to a known block number and let Alice lock in a guess
        vm.roll(fuzzBlockNumber);
        vm.prank(alice);
        bytes32 guess = bytes32(uint256(1));
        c.lockInGuess{value: 1 ether}(guess);

        // Advance blocks to allow settlement
        vm.roll(fuzzBlockNumber + fuzzBlockDelta);

        // Attempt settle; do not check revert
        vm.prank(alice);
        try c.settle() {} catch {}

        // The invariant: after any call to settle(), the caller's block field MUST be 0
        // This is the general rule: settle always clears guesses[caller].block
        (uint blockStored, bytes32 guessStored) = c.guesses(alice);
        assertTrue(blockStored == 0);
    }
}

