pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(bytes32 guess, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(this));
        vm.assume(actor != address(c));
        // deploy contract with 2 ether so payouts can happen
        vm.deal(address(c), 2 ether);
        // fund actor for lockInGuess
        vm.deal(actor, 1 ether);
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(guess);
        // advance block past lock block
        vm.roll(block.number + 2);
        uint256 balBefore = address(c).balance;
        vm.prank(actor);
        try c.settle() { } catch { }
        uint256 balAfter = address(c).balance;
        // If the settlement succeeded in paying out (guess matched blockhash),
        // the balance change must be exactly 2 ether less.
        // In the mutant, after payout the block is not zeroed, so calling settle again
        // can succeed and drain additional funds, making the net balance change > 2 ether over time.
        // This rule: after any single settle call, the balance decrease is either 0 (if guess wrong)
        // or exactly 2 ether (if correct). The mutant can decrease by more than 2 ether because
        // repeated settles without re-locking can drain contract.
        // Actually, we check a stricter invariant: if settle did not revert and guess was correct,
        // then balance decreased by exactly 2 ether. But here we simply assert:
        // balance change is 0 or 2 ether.
        assertTrue(balBefore - balAfter == 0 || balBefore - balAfter == 2 ether);
    }
}

