pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(bytes32 guess, uint256 blockOffset) public {
        // Keep blockOffset small so block.number + blockOffset is reachable, but wide enough to find the right condition.
        bound(blockOffset, 2, 256);
        vm.assume(guess != bytes32(0));

        // Setup: fund the contract with at least 2 ether so payment is possible.
        address someone = address(0x1234);
        vm.deal(someone, 10 ether);
        vm.prank(someone);
        // deploy with 1 ether
        C funded = new C{value: 1 ether}();
        // send extra 1 ether so balance >= 2 ether
        vm.deal(address(this), 10 ether);
        (bool sent, ) = address(funded).call{value: 1 ether}("");
        require(sent, "funding failed");

        address guesser = address(0x5678);
        vm.deal(guesser, 10 ether);

        // lockInGuess
        vm.prank(guesser);
        funded.lockInGuess{value: 1 ether}(guess);

        uint256 targetBlock = block.number + 1;
        // advance to targetBlock + blockOffset
        vm.roll(targetBlock + blockOffset);
        require(block.number > targetBlock, "did not advance");

        // Drive settle and observe payment
        uint256 balBefore = guesser.balance;
        vm.prank(guesser);
        try funded.settle() {} catch {}
        uint256 balAfter = guesser.balance;

        bool paidOut = (balAfter > balBefore);

        // General rule: payout occurs ONLY if guess equals the correct answer.
        // Recompute the correct answer the same way the contract does.
        bytes32 expectedAnswer = keccak256(abi.encodePacked(blockhash(targetBlock)));
        bool guessIsCorrect = (guess == expectedAnswer);

        assertTrue(paidOut == guessIsCorrect);
    }
}

