        vm.assume(guesser != address(0) && guesser != address(c));
        vm.assume(!(guess == keccak256(abi.encodePacked(blockhash(block.number + 1)))));

        vm.deal(guesser, 1 ether);
        vm.prank(guesser);
        c.lockInGuess{value: 1 ether}(guess);

        vm.roll(block.number + blockShift);

        uint256 balanceBefore = address(c).balance;
        bool ok;
        try c.settle() {
            ok = true;
        } catch {
            ok = false;
        }
        uint256 balanceAfter = address(c).balance;

