pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(bytes32 guess, uint256 advance) public {
        // Admissible domain: advance must be > 0 and <= 256 to ensure blockhash is non-zero
        vm.assume(advance > 0 && advance <= 256);
        address player = address(0x1234);
        vm.deal(player, 1 ether);
        vm.prank(player);
        c.lockInGuess{value: 1 ether}(guess);
        vm.roll(block.number + advance);
        vm.prank(player);
        uint256 balanceBefore = address(c).balance;
        bool ok;
        try c.settle() { ok = true; } catch { ok = false; }
        // General rule: after a successful settle where the guess matches the answer,
        // the contract's balance must decrease by exactly 2 ether.
        // The mutant changes the reference block, so condition `guesses[msg.sender].guess == answer` becomes false
        // where it was true in the reference, thus the transfer never happens and balance remains unchanged.
        bool matches = (ok && (address(c).balance < balanceBefore));
        assertTrue(balanceBefore - address(c).balance == 2 ether || !matches);
    }
}

