pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address sender, bytes32 guessHash, uint48 settleBlockOffset) public {
        vm.assume(sender != address(0));
        vm.assume(settleBlockOffset > 1);

        // Setup: fund sender and call lockInGuess
        vm.deal(sender, 1 ether);
        vm.prank(sender);
        c.lockInGuess{value: 1 ether}(guessHash);

        // Advance to the settle block
        uint settleBlock = block.number + settleBlockOffset;
        vm.roll(settleBlock);

        // Try settling
        vm.prank(sender);
        bool ok;
        try c.settle() {
            ok = true;
        } catch {
            ok = false;
        }

        if (ok) {
            // When settle succeeds, the sender's guess must equal keccak256 of the reference block hash
            uint storedBlock = settleBlock - settleBlockOffset;
            bytes32 expectedAnswer = keccak256(abi.encodePacked(blockhash(storedBlock)));
            // The public getter for guesses mapping gives the guess value
            ( , bytes32 storedGuess) = c.guesses(sender);
            assertTrue(storedGuess == expectedAnswer);
        }
    }
}

